/* Modern Theme - Contemporary Design */

:root {
  /* Light Theme Colors */
  --modern-bg: #F8F9FA;
  --modern-surface: #FFFFFF;
  --modern-surface-light: #F1F3F4;
  --modern-surface-dark: #E9ECEF;
  --modern-border: #DEE2E6;
  --modern-text: #495057;
  --modern-text-bright: #212529;
  --modern-accent: #6366F1;
  --modern-accent-hover: #4F46E5;
  --modern-success: #10B981;
  --modern-warning: #F59E0B;
  --modern-danger: #EF4444;
  --modern-info: #3B82F6;
  --modern-secondary: #6B7280;

  /* Override Bootstrap Variables */
  --bs-body-bg: var(--modern-bg);
  --bs-body-color: var(--modern-text);
  --bs-card-bg: var(--modern-surface);
  --bs-card-border-color: var(--modern-border);
  --bs-border-color: var(--modern-border);
  --bs-primary: var(--modern-accent);
  --bs-primary-rgb: 99, 102, 241;
  --bs-success: var(--modern-success);
  --bs-success-rgb: 16, 185, 129;
  --bs-warning: var(--modern-warning);
  --bs-warning-rgb: 245, 158, 11;
  --bs-danger: var(--modern-danger);
  --bs-danger-rgb: 239, 68, 68;
  --bs-info: var(--modern-info);
  --bs-info-rgb: 59, 130, 246;
  --bs-secondary: var(--modern-secondary);
  --bs-secondary-rgb: 107, 114, 128;
}

/* Global Body Styles */
body {
  background-color: var(--modern-bg) !important;
  color: var(--modern-text) !important;
  font-family: 'Inter', 'Segoe UI', system-ui, sans-serif !important;
