}

.card-header {
  background: linear-gradient(135deg, var(--modern-surface-light) 0%, var(--modern-surface) 100%) !important;
  border-bottom: 1px solid var(--modern-border) !important;
  color: var(--modern-text-bright) !important;
  border-radius: 12px 12px 0 0 !important;
}

.card-title {
  color: var(--modern-text-bright) !important;
  font-weight: 600;
}

/* Dashboard Cards */
.dashboard-card {
  background-color: var(--modern-surface) !important;
  border: 1px solid var(--modern-border) !important;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06) !important;
  border-radius: 16px !important;
}

.metric-card {
