.dropdown-item:hover, .dropdown-item:focus {
  background-color: var(--darcula-surface-light) !important;
  color: var(--darcula-text-bright) !important;
}

.dropdown-item.active {
  background-color: var(--darcula-accent) !important;
  color: var(--darcula-text-bright) !important;
}

/* Footer */
footer {
  background: linear-gradient(135deg, var(--modern-surface) 0%, var(--modern-surface-light) 100%) !important;
  border-top: 1px solid var(--modern-border);
  color: var(--modern-text) !important;
}

/* Progress bars */
.progress {
  background-color: var(--modern-surface-light) !important;
  border-radius: 8px !important;
  height: 8px !important;
}

.progress-bar {
  background: linear-gradient(90deg, var(--modern-accent), var(--modern-accent-hover)) !important;
  border-radius: 8px !important;
}

/* Chart Container */
.chart-container {
  background-color: var(--modern-surface) !important;
  border: 1px solid var(--modern-border) !important;
  border-radius: 12px !important;
}

/* Text colors */
.text-muted {
  color: var(--modern-secondary) !important;
}

.text-success {
  color: var(--modern-success) !important;
}

.text-primary {
  color: var(--modern-accent) !important;
}

/* Modal */
.modal-content {
  background-color: var(--darcula-surface) !important;
  border: 1px solid var(--darcula-border) !important;
}

.modal-header, .modal-footer {
  border-color: var(--darcula-border) !important;
}

.modal-title {
  color: var(--darcula-text-bright) !important;
}

/* Close button */
.btn-close {
  filter: invert(1) grayscale(100%) brightness(200%);
}

/* Timeline for history */
.timeline-item {
  position: relative;
}

.timeline-item::before {
  content: '';
  position: absolute;
  left: -15px;
  top: 12px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--darcula-accent);
  border: 2px solid var(--darcula-bg);
}

/* Custom scrollbars */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: var(--modern-surface-light);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb {
  background: var(--modern-border);
  border-radius: 4px;
  transition: background 0.3s ease;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--modern-secondary);
}

/* Input group */
.input-group-text {
  background-color: var(--modern-surface-light) !important;
  border-color: var(--modern-border) !important;
  color: var(--modern-text) !important;
  border-radius: 8px !important;
}

/* Additional Modern Enhancements */
.rounded {
  border-radius: 12px !important;
}

.shadow {
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06) !important;
}

.shadow-lg {
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05) !important;
}

/* Smooth transitions for all interactive elements */
* {
  transition: all 0.3s ease;
}

/* ===== DARK THEME ===== */
[data-theme="dark"] {
  /* Dark Theme Colors */
  --modern-bg: #1a1a1a;
  --modern-surface: #2d2d2d;
  --modern-surface-light: #3a3a3a;
  --modern-surface-dark: #0f0f0f;
  --modern-border: #404040;
  --modern-text: #e5e5e5;
  --modern-text-bright: #ffffff;
  --modern-accent: #818cf8;
  --modern-accent-hover: #a5b4fc;
  --modern-success: #34d399;
  --modern-warning: #fbbf24;
  --modern-danger: #f87171;
  --modern-info: #60a5fa;
  --modern-secondary: #9ca3af;

  /* Override Bootstrap Variables for Dark Theme */
  --bs-body-bg: var(--modern-bg);
  --bs-body-color: var(--modern-text);
  --bs-card-bg: var(--modern-surface);
  --bs-card-border-color: var(--modern-border);
  --bs-border-color: var(--modern-border);
  --bs-primary: var(--modern-accent);
  --bs-primary-rgb: 129, 140, 248;
  --bs-success: var(--modern-success);
  --bs-success-rgb: 52, 211, 153;
  --bs-warning: var(--modern-warning);
  --bs-warning-rgb: 251, 191, 36;
  --bs-danger: var(--modern-danger);
  --bs-danger-rgb: 248, 113, 113;
  --bs-info: var(--modern-info);
  --bs-info-rgb: 96, 165, 250;
  --bs-secondary: var(--modern-secondary);
  --bs-secondary-rgb: 156, 163, 175;
}

/* Dark theme specific adjustments */
[data-theme="dark"] .navbar {
  background: linear-gradient(135deg, var(--modern-surface-dark) 0%, var(--modern-surface) 100%) !important;
  box-shadow: 0 1px 3px 0 rgba(255, 255, 255, 0.1), 0 1px 2px 0 rgba(255, 255, 255, 0.06);
}

[data-theme="dark"] .card:hover {
  box-shadow: 0 4px 6px -1px rgba(255, 255, 255, 0.1), 0 2px 4px -1px rgba(255, 255, 255, 0.06) !important;
}

[data-theme="dark"] .table-hover tbody tr:hover {
  background-color: rgba(129, 140, 248, 0.1) !important;
}

[data-theme="dark"] .table-striped tbody tr:nth-of-type(odd) {
  background-color: rgba(129, 140, 248, 0.05) !important;
}

[data-theme="dark"] .form-control:focus, 
[data-theme="dark"] .form-select:focus {
  box-shadow: 0 0 0 3px rgba(129, 140, 248, 0.15) !important;
}

[data-theme="dark"] .alert-primary {
  background: linear-gradient(135deg, rgba(129, 140, 248, 0.15), rgba(129, 140, 248, 0.08)) !important;
}

[data-theme="dark"] .alert-success {
  background: linear-gradient(135deg, rgba(52, 211, 153, 0.15), rgba(52, 211, 153, 0.08)) !important;
}

[data-theme="dark"] .alert-warning {
  background: linear-gradient(135deg, rgba(251, 191, 36, 0.15), rgba(251, 191, 36, 0.08)) !important;
}

[data-theme="dark"] .alert-danger {
  background: linear-gradient(135deg, rgba(248, 113, 113, 0.15), rgba(248, 113, 113, 0.08)) !important;
}

[data-theme="dark"] .alert-info {
  background: linear-gradient(135deg, rgba(96, 165, 250, 0.15), rgba(96, 165, 250, 0.08)) !important;
}

[data-theme="dark"] ::-webkit-scrollbar-track {
  background: var(--modern-surface-dark);
}

[data-theme="dark"] ::-webkit-scrollbar-thumb {
  background: var(--modern-border);
}

[data-theme="dark"] ::-webkit-scrollbar-thumb:hover {
  background: var(--modern-secondary);
}

/* Theme toggle button */
#themeToggle {
  border: none !important;
  background: transparent !important;
  color: var(--modern-text) !important;
  border-radius: 8px !important;
  width: 40px !important;
  height: 40px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  transition: all 0.3s ease !important;
}

#themeToggle:hover {
  background: var(--modern-surface-light) !important;
  color: var(--modern-accent) !important;
  transform: scale(1.1);
}

static/css/planner.css.content:
/* Planner/Kanban Board Styles */
.planner-container {
    max-width: 100%;
    margin: 0 auto;
}

.kanban-board {
    display: flex;
    gap: 20px;
    overflow-x: auto;
    padding: 20px 0;
    min-height: 600px;
}

.kanban-list {
    min-width: 280px;
    max-width: 280px;
    background: var(--bs-card-bg, #1e1e1e);
    border-radius: 8px;
    border: 1px solid var(--bs-border-color, #333);
    display: flex;
    flex-direction: column;
    max-height: 70vh;
}

.list-header {
    padding: 15px;
    border-bottom: 1px solid var(--bs-border-color, #333);
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: var(--bs-card-cap-bg, #2a2a2a);
    border-radius: 8px 8px 0 0;
}

.list-title {
    margin: 0;
    color: var(--bs-body-color, #fff);
    font-weight: 600;
}

.list-actions {
    display: flex;
    gap: 5px;
}

.task-container {
    flex: 1;
    padding: 15px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.task-card {
    background: var(--bs-body-bg, #2d2d2d);
    border: 1px solid var(--bs-border-color, #404040);
    border-radius: 6px;
    padding: 12px;
    cursor: pointer;
    transition: all 0.2s ease;
    position: relative;
}

.task-card:hover {
    border-color: var(--bs-primary, #0d6efd);
    transform: translateY(-1px);
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
}

.task-card.dragging {
    opacity: 0.5;
    transform: rotate(5deg);
}

.task-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 8px;
}

.task-title {
    margin: 0;
    font-size: 14px;
    font-weight: 600;
    color: var(--bs-body-color, #fff);
    flex: 1;
    margin-right: 8px;
}

.priority-badge {
    font-size: 10px;
    padding: 2px 6px;
    border-radius: 12px;
    color: white;
    font-weight: 500;
    text-transform: uppercase;
}

.task-description {
    font-size: 12px;
    color: var(--bs-secondary-color, #adb5bd);
    margin: 8px 0;
    line-height: 1.4;
}

.task-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 8px;
    font-size: 11px;
}

.due-date {
    color: var(--bs-secondary-color, #adb5bd);
}

.due-date.overdue {
    color: var(--bs-danger, #dc3545);
    font-weight: 600;
}

.task-actions {
    display: flex;
    gap: 4px;
    opacity: 0;
    transition: opacity 0.2s ease;
}

.task-card:hover .task-actions {
    opacity: 1;
}

.add-list-placeholder {
    min-width: 280px;
    background: var(--bs-card-bg, #1e1e1e);
    border: 2px dashed var(--bs-border-color, #333);
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s ease;
    color: var(--bs-secondary-color, #adb5bd);
    height: 120px;
}

.add-list-placeholder:hover {
    border-color: var(--bs-primary, #0d6efd);
    color: var(--bs-primary, #0d6efd);
    transform: translateY(-2px);
}

.add-list-placeholder i {
    font-size: 24px;
    margin-bottom: 8px;
}

/* Drag and Drop Styles */
.task-container.drag-over {
    background: rgba(13, 110, 253, 0.1);
    border: 2px dashed var(--bs-primary, #0d6efd);
    border-radius: 6px;
}

.task-container.drag-over::after {
    content: "Solte aqui";
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    color: var(--bs-primary, #0d6efd);
    font-weight: 600;
    pointer-events: none;
}

/* Responsive Design */
@media (max-width: 768px) {
    .kanban-board {
        flex-direction: column;
        gap: 15px;
    }

    .kanban-list {
        min-width: 100%;
        max-width: 100%;
        max-height: none;
    }

    .add-list-placeholder {
        min-width: 100%;
    }
}

/* Dark theme enhancements */
[data-theme="dark"] .kanban-list {
    background: #1a1a1a;
    border-color: #333;
}

[data-theme="dark"] .list-header {
    background: #252525;
    border-color: #333;
}

[data-theme="dark"] .task-card {
    background: #2a2a2a;
    border-color: #404040;
}

[data-theme="dark"] .task-card:hover {
    border-color: #0d6efd;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.4);
}

[data-theme="dark"] .add-list-placeholder {
    background: #1a1a1a;
    border-color: #333;
}

[data-theme="dark"] .add-list-placeholder:hover {
    border-color: #0d6efd;
}

/* Animation for new items */
@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateX(-20px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

.kanban-list.new-item,
.task-card.new-item {
    animation: slideIn 0.3s ease-out;
}

/* Success feedback */
.success-feedback {
    position: fixed;
    top: 20px;
    right: 20px;
    background: var(--bs-success, #198754);
    color: white;
    padding: 12px 20px;
    border-radius: 6px;
    z-index: 1060;
    animation: slideIn 0.3s ease-out;
}

/* Checklist Styles */
.checklist-progress {
    margin: 8px 0;
}

.progress-bar-container {
    background: var(--bs-border-color, #333);
    height: 6px;
    border-radius: 3px;
    overflow: hidden;
    margin-bottom: 4px;
}

.progress-bar {
    background: var(--bs-success, #198754);
    height: 100%;
    transition: width 0.3s ease;
    border-radius: 3px;
}

.progress-text {
    color: var(--bs-secondary-color, #adb5bd);
    font-size: 11px;
}

.checklist-progress-section .progress-bar-container {
    height: 12px;
    margin-bottom: 8px;
}

.checklist-progress-section .progress-text {
    font-size: 14px;
    font-weight: 500;
}

.checklist-items {
    max-height: 300px;
    overflow-y: auto;
}

.checklist-item {
    display: flex;
    align-items: center;
    padding: 8px 12px;
    border: 1px solid var(--bs-border-color, #333);
    border-radius: 6px;
    margin-bottom: 8px;
    background: var(--bs-body-bg, #2d2d2d);
    transition: all 0.2s ease;
}

.checklist-item:hover {
    border-color: var(--bs-primary, #0d6efd);
}

.checklist-item.completed {
    opacity: 0.7;
}

.checklist-item.completed .checklist-text {
    text-decoration: line-through;
}

.checklist-checkbox {
    margin-right: 12px;
    cursor: pointer;
}

.checklist-text {
    flex: 1;
    color: var(--bs-body-color, #fff);
    margin: 0;
}

.checklist-actions {
    opacity: 0;
    transition: opacity 0.2s ease;
}

.checklist-item:hover .checklist-actions {
    opacity: 1;
}

.add-checklist-item input:focus {
    border-color: var(--bs-primary, #0d6efd);
    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.25);
}

/* Form background fixes */
.modal-content {
    background-color: var(--bs-modal-bg, #1a1a1a) !important;
    border: 1px solid var(--bs-border-color, #333) !important;
}

[data-theme="dark"] .modal-content {
    background-color: #1a1a1a !important;
    border-color: #333 !important;
}

.form-control {
    background-color: var(--bs-body-bg, #2d2d2d) !important;
    border-color: var(--bs-border-color, #404040) !important;
    color: var(--bs-body-color, #fff) !important;
}

.form-control:focus {
    background-color: var(--bs-body-bg, #2d2d2d) !important;
    border-color: var(--bs-primary, #0d6efd) !important;
    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.25) !important;
}

.form-select {
    background-color: var(--bs-body-bg, #2d2d2d) !important;
    border-color: var(--bs-border-color, #404040) !important;
    color: var(--bs-body-color, #fff) !important;
}

[data-theme="dark"] .form-control,
[data-theme="dark"] .form-select {
    background-color: #2a2a2a !important;
    border-color: #404040 !important;
    color: #fff !important;
}

static/js/dashboard.js.content:
// Dashboard specific JavaScript functions
document.addEventListener('DOMContentLoaded', function() {
    // Initialize tooltips
    var tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));
    var tooltipList = tooltipTriggerList.map(function(tooltipTriggerEl) {
        return new bootstrap.Tooltip(tooltipTriggerEl);
    });

    // Auto-refresh dashboard data every 5 minutes
    setInterval(function() {
        if (document.hidden === false) {
            // Only refresh if page is visible
            window.location.reload();
        }
    }, 300000); // 5 minutes

    // Add animation to KPI cards
    const cards = document.querySelectorAll('.card');
    cards.forEach((card, index) => {
        card.style.opacity = '0';
        card.style.transform = 'translateY(20px)';

        setTimeout(() => {
            card.style.transition = 'all 0.5s ease';
            card.style.opacity = '1';
            card.style.transform = 'translateY(0)';
        }, index * 100);
    });
});

// Function to format currency values
function formatCurrency(value) {
    return new Intl.NumberFormat('pt-BR', {
        style: 'currency',
        currency: 'BRL'
    }).format(value);
}

// Function to update dashboard stats via AJAX (if needed)
function updateDashboardStats() {
    fetch('/api/dashboard-stats')
        .then(response => response.json())
        .then(data => {
            // Update KPI cards with new data
            document.querySelector('#total-equipment').textContent = data.total;
            document.querySelector('#equipment-in-use').textContent = data.em_uso;
            document.querySelector('#equipment-no-antivirus').textContent = data.sem_antivirus;
            document.querySelector('#equipment-no-term').textContent = data.sem_termo;
            document.querySelector('#total-value').textContent = formatCurrency(data.valor_total);
        })
        .catch(error => {
            console.error('Error updating dashboard stats:', error);
        });
}

static/js/equipment.js.content:
// Equipment specific JavaScript functions
document.addEventListener('DOMContentLoaded', function() {
    // Initialize tooltips
    var tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));
    var tooltipList = tooltipTriggerList.map(function(tooltipTriggerEl) {
        return new bootstrap.Tooltip(tooltipTriggerEl);
    });

    // Auto-submit search form on input change
    const searchForm = document.getElementById('search-form');
    if (searchForm) {
        const searchInputs = searchForm.querySelectorAll('input, select');
        searchInputs.forEach(input => {
            if (input.type !== 'submit') {
                input.addEventListener('change', function() {
                    // Debounce for text inputs
                    if (this.type === 'text') {
                        clearTimeout(this.searchTimeout);
                        this.searchTimeout = setTimeout(() => {
                            searchForm.submit();
                        }, 500);
                    } else {
                        searchForm.submit();
                    }
                });
            }
        });
    }

    // Add sorting functionality to table headers
    const tableHeaders = document.querySelectorAll('th[data-sort]');
    tableHeaders.forEach(header => {
        header.style.cursor = 'pointer';
        header.addEventListener('click', function() {
            const sortField = this.dataset.sort;
            const currentUrl = new URL(window.location);
            const currentSort = currentUrl.searchParams.get('sort');
            const currentOrder = currentUrl.searchParams.get('order');

            let newOrder = 'asc';
            if (currentSort === sortField && currentOrder === 'asc') {
                newOrder = 'desc';
            }

            currentUrl.searchParams.set('sort', sortField);
            currentUrl.searchParams.set('order', newOrder);
            window.location.href = currentUrl.toString();
        });
    });

    // Add row highlighting on hover
    const tableRows = document.querySelectorAll('tbody tr');
    tableRows.forEach(row => {
        row.addEventListener('mouseenter', function() {
            this.style.backgroundColor = 'rgba(0, 123, 255, 0.1)';
        });

        row.addEventListener('mouseleave', function() {
            this.style.backgroundColor = '';
        });
    });
});

// Function to confirm deletion
function confirmDelete(equipmentId, equipmentName) {
    if (confirm(`Tem certeza que deseja excluir o equipamento "${equipmentName}"?\n\nEsta ação não pode ser desfeita.`)) {
        // Create a form to submit the delete request
        const form = document.createElement('form');
        form.method = 'POST';
        form.action = `/equipment/${equipmentId}/delete`;

        // Add CSRF token if available
        const csrfToken = document.querySelector('meta[name=csrf-token]');
        if (csrfToken) {
            const tokenInput = document.createElement('input');
            tokenInput.type = 'hidden';
            tokenInput.name = 'csrf_token';
            tokenInput.value = csrfToken.getAttribute('content');
            form.appendChild(tokenInput);
        }

        document.body.appendChild(form);
        form.submit();
    }
}

// Function to export data
function exportData(format) {
    const currentUrl = new URL(window.location);
    const params = currentUrl.searchParams;

    let exportUrl = `/export/${format}`;
    if (params.toString()) {
        exportUrl += `?${params.toString()}`;
    }

    window.location.href = exportUrl;
}

// Function to toggle advanced search
function toggleAdvancedSearch() {
    const advancedDiv = document.getElementById('advanced-search');
    const toggleBtn = document.getElementById('toggle-advanced');

    if (advancedDiv.style.display === 'none') {
        advancedDiv.style.display = 'block';
        toggleBtn.textContent = 'Ocultar Filtros Avançados';
    } else {
        advancedDiv.style.display = 'none';
        toggleBtn.textContent = 'Mostrar Filtros Avançados';
    }
}

// Function to clear all filters
function clearFilters() {
    const form = document.getElementById('search-form');
    const inputs = form.querySelectorAll('input, select');

    inputs.forEach(input => {
        if (input.type === 'text' || input.type === 'email' || input.type === 'tel') {
            input.value = '';
        } else if (input.type === 'select-one') {
            input.selectedIndex = 0;
        } else if (input.type === 'checkbox') {
            input.checked = false;
        }
    });

    // Remove URL parameters and reload
    window.location.href = window.location.pathname;
}

// Function to validate form before submission
function validateEquipmentForm() {
    const form = document.querySelector('form');
    const requiredFields = form.querySelectorAll('[required]');
    let isValid = true;

    requiredFields.forEach(field => {
        if (!field.value.trim()) {
            field.classList.add('is-invalid');
            isValid = false;
        } else {
            field.classList.remove('is-invalid');
        }
    });

    return isValid;
}

// Add form validation on submit
document.addEventListener('DOMContentLoaded', function() {
    const equipmentForm = document.querySelector('form[method="POST"]');
    if (equipmentForm) {
        equipmentForm.addEventListener('submit', function(e) {
            if (!validateEquipmentForm()) {
                e.preventDefault();
                alert('Por favor, preencha todos os campos obrigatórios.');
            }
        });
    }
});

